# break — остановить цикл
for num in range(1, 20):
    if num > 5:
        break
    print(num)

# continue — пропустить итерацию
for num in range(1, 6):
    if num == 3:
        continue
    print(num)  # пропустит 3

# Таблица умножения 1-3
for i in range(1, 4):
    for j in range(1, 4):
        print(f"{i * j}", end=" ")
    print()  # перенос строки после внутреннего цикла
